    <script type="module">
        /* 更新进度条辅助函数 */
        function updateProgressBar(barId, valueId, rawValue, min = 0, max = 100, color = null) {
            const numericValue = parseFloat(rawValue);
            if (!isNaN(numericValue)) {
                const clampedValue = _.clamp(numericValue, min, max);
                const percentage = max - min === 0 ? 0 : ((clampedValue - min) / (max - min)) * 100;

                $(`#${valueId}`).text(clampedValue);
                const cssProps = { width: `${percentage}%` };
                if (color) {
                    cssProps.backgroundImage = 'none';
                    cssProps.backgroundColor = color;
                }
                $(`#${barId}`).css(cssProps);
            } else {
                $(`#${valueId}`).text(rawValue);
            }
        }

        /* 根据 "HH:MM" 字符串旋转指针，展示当前剧情时间 */
        function updateStoryClock(timeStr) {
            const match = /^(\d{1,2}):(\d{1,2})$/.exec(_.trim(timeStr));
            let hours = 0;
            let minutes = 0;
            if (match) {
                hours = parseInt(match[1], 10) % 12;
                minutes = parseInt(match[2], 10);
            }
            const hourDeg = hours * 30 + minutes * 0.5;
            const minuteDeg = minutes * 6;
            $('#clock-hour-hand').css('transform', `rotate(${hourDeg}deg)`);
            $('#clock-minute-hand').css('transform', `rotate(${minuteDeg}deg)`);
            $('#clock-time-label').text(match ? timeStr : '--:--');
        }

        /* 填充状态栏数据 */
        function populateCharacterData() {
            try {
                const all_variables = getAllVariables();
                const characterData = all_variables.stat_data;

                if (!characterData) {
                    $('#status-card').html("<div class='error-tip'>无法加载状态数据</div>");
                    return;
                }

                /* 剧情时间：驱动右上角的指针钟 */
                updateStoryClock(_.get(characterData, '时间', '00:00'));

                /* Krueger 好感度：范围 0 ~ 100 */
                updateProgressBar(
                    'krueger-affection-bar',
                    'krueger-affection',
                    _.get(characterData, 'Krueger.好感度', 0),
                    0, 100, '#a5813f'
                );

                /* Krueger 性欲值：范围 0 ~ 100 */
                updateProgressBar(
                    'krueger-desire-bar',
                    'krueger-desire',
                    _.get(characterData, 'Krueger.性欲值', 0),
                    0, 100, '#7a5a2e'
                );

                /* Krueger 伪装破绽度：范围 0 ~ 100 */
                updateProgressBar(
                    'krueger-facade-bar',
                    'krueger-facade',
                    _.get(characterData, 'Krueger.伪装破绽度', 0),
                    0, 100, '#3f6b4a'
                );

                /* 文本类属性 */
                $('#krueger-outfit').text(_.get(characterData, 'Krueger.衣着', 'N/A'));
                $('#krueger-status-badge').text(_.get(characterData, 'Krueger.状态', 'N/A'));
                $('#krueger-inner-voice').text(_.get(characterData, 'Krueger.心声', 'N/A'));
            } catch (error) {
                $('#status-card').html(`<div class='error-tip'>状态栏加载出错: ${error.message}</div>`);
            }
        }

        /* 初始化 */
        async function init() {
            /* 等待 MVU 系统初始化完成 */
            await waitGlobalInitialized('Mvu');

            /* 填充数据 */
            populateCharacterData();
        }

        $(errorCatched(init));
    </script>
</head>
